package com.example.proyectolp.controller;

import com.example.proyectolp.config.AppConfig;
import com.example.proyectolp.model.TrainingModels.*;
import com.example.proyectolp.repository.*;
import com.example.proyectolp.service.*;
import javafx.collections.FXCollections;
import javafx.concurrent.Task;
import javafx.fxml.FXML;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.chart.XYChart;
import javafx.scene.control.*;
import javafx.stage.Modality;
import javafx.stage.Stage;
import java.io.IOException;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;

public class TrainingController {
    @FXML private ListView<Routine> routineList; @FXML private ComboBox<Routine> sessionRoutine; @FXML private ComboBox<Exercise> sessionExercise,progressExercise;
    @FXML private ListView<Session> sessionHistoryList; @FXML private Button btnSessionAttachments, btnHistoryAttachments;
    @FXML private DatePicker sessionDate; @FXML private TextField weightField,repsField,commentField,timerConfig;
    @FXML private ComboBox<String> distributionPeriod;
    @FXML private Label messageLabel,timerLabel,sessionVolumeLabel,comparisonLabel,weeklyLabel,monthlyLabel,frequencyLabel,statsLabel;
    @FXML private TableView<SetEntry> setTable; @FXML private TableColumn<SetEntry,String> setExerciseCol,setMuscleCol; @FXML private TableColumn<SetEntry,Number> setNumberCol,setRepsCol; @FXML private TableColumn<SetEntry,BigDecimal> setWeightCol;
    @FXML private javafx.scene.chart.LineChart<String,Number> progressChart; @FXML private javafx.scene.chart.PieChart muscleChart;
    private final ExecutorService executor=SessionTaskExecutor.get();
    private final TrainingStatsService stats=new TrainingStatsService(); private final RestTimer timer=new RestTimer();
    private List<Routine> routines=new ArrayList<>(); private List<Session> sessions=new ArrayList<>(); private List<SetEntry> sets=new ArrayList<>(); private Long currentSessionId; private boolean sessionFinished;
    private Parent dashboardRoot; private DashboardController dashboard;
    @FXML private void initialize(){sessionDate.setValue(LocalDate.now());distributionPeriod.setItems(FXCollections.observableArrayList("Semana","Mes"));distributionPeriod.getSelectionModel().selectFirst();distributionPeriod.valueProperty().addListener((o,a,b)->renderMuscles());routineList.setCellFactory(v->new ListCell<>(){@Override protected void updateItem(Routine r,boolean empty){super.updateItem(r,empty);setText(empty||r==null?null:r.name());}});sessionRoutine.setCellFactory(v->new ListCell<>(){@Override protected void updateItem(Routine r,boolean empty){super.updateItem(r,empty);setText(empty||r==null?null:r.name());}});sessionRoutine.setButtonCell(new ListCell<>(){@Override protected void updateItem(Routine r,boolean empty){super.updateItem(r,empty);setText(empty||r==null?"Sesión libre":r.name());}});setExerciseCell(sessionExercise);setExerciseCell(progressExercise);setTable.setItems(FXCollections.observableArrayList());setExerciseCol.setCellValueFactory(v->new javafx.beans.property.SimpleStringProperty(v.getValue().exerciseName()));setMuscleCol.setCellValueFactory(v->new javafx.beans.property.SimpleStringProperty(v.getValue().muscleGroup()));setNumberCol.setCellValueFactory(v->new javafx.beans.property.SimpleIntegerProperty(v.getValue().setNumber()));setWeightCol.setCellValueFactory(v->new javafx.beans.property.SimpleObjectProperty<>(v.getValue().weight()));setRepsCol.setCellValueFactory(v->new javafx.beans.property.SimpleIntegerProperty(v.getValue().reps()));timer.remainingSecondsProperty().addListener((o,a,b)->timerLabel.setText(timer.getDisplay()));timer.stateProperty().addListener((o,a,b)->timerLabel.setStyle(b==RestTimer.State.FINISHED?"-fx-text-fill: #b42318; -fx-font-size: 20px; -fx-font-weight: bold;":"-fx-font-size: 20px; -fx-font-weight: bold;"));sessionRoutine.valueProperty().addListener((o,a,b)->{if(b!=null)sessionExercise.setItems(FXCollections.observableArrayList(b.exercises()));else sessionExercise.getItems().clear();});sessionHistoryList.getSelectionModel().selectedItemProperty().addListener((o,a,b)->btnHistoryAttachments.setDisable(b==null));loadData();}
    public void setDashboard(Parent root,DashboardController controller){dashboardRoot=root;dashboard=controller;}
    private void setExerciseCell(ComboBox<Exercise> combo){combo.setCellFactory(v->new ListCell<>(){@Override protected void updateItem(Exercise e,boolean empty){super.updateItem(e,empty);setText(empty||e==null?null:e.name()+" · "+e.muscleGroup());}});combo.setButtonCell(new ListCell<>(){@Override protected void updateItem(Exercise e,boolean empty){super.updateItem(e,empty);setText(empty||e==null?"Ejercicio":e.name());}});}
    private SupabaseService db() throws Exception{return new SupabaseService(AppConfig.load());}
    private void loadData(){messageLabel.setText("Cargando…");Task<Loaded> task=new Task<>(){@Override protected Loaded call()throws Exception{SupabaseService s=db();return new Loaded(new WorkoutRoutineRepository(s).list(),new WorkoutSessionRepository(s).list(),new WorkoutSetRepository(s).list());}};task.setOnSucceeded(e->{Loaded d=task.getValue();routines=d.routines;sessions=d.sessions;sets=d.sets;sessionHistoryList.setItems(FXCollections.observableArrayList(sessions));sessionHistoryList.setCellFactory(v->new ListCell<>(){@Override protected void updateItem(Session x,boolean empty){super.updateItem(x,empty);if(empty||x==null){setText(null);return;}String rn=routines.stream().filter(r->Objects.equals(r.id(),x.routineId())).map(Routine::name).findFirst().orElse("Sesión libre");long n=sets.stream().filter(z->Objects.equals(z.sessionId(),x.id())).count();setText(x.sessionDate()+" · "+rn+" · "+n+" series");}});routineList.setItems(FXCollections.observableArrayList(routines));sessionRoutine.setItems(FXCollections.observableArrayList(routines));refreshViews();refreshProgress();messageLabel.setText("");});task.setOnFailed(e->messageLabel.setText(readable(task.getException())));executor.submit(task);}
    private record Loaded(List<Routine> routines,List<Session> sessions,List<SetEntry> sets){}
    @FXML private void newRoutine(){showRoutineForm(null);}
    @FXML private void openCurrentSessionAttachments(){if(currentSessionId==null){messageLabel.setText("Inicia y guarda una sesión antes de adjuntar archivos.");return;}AttachmentsDialog.show(messageLabel.getScene().getWindow(),com.example.proyectolp.model.enums.AttachmentOwnerType.SESSION,currentSessionId,"Adjuntos de la sesión");}
    @FXML private void openHistoryAttachments(){Session selected=sessionHistoryList.getSelectionModel().getSelectedItem();if(selected!=null)AttachmentsDialog.show(messageLabel.getScene().getWindow(),com.example.proyectolp.model.enums.AttachmentOwnerType.SESSION,selected.id(),"Adjuntos de la sesión");}
    @FXML private void editRoutine(){Routine r=routineList.getSelectionModel().getSelectedItem();if(r==null){messageLabel.setText("Selecciona una rutina.");return;}showRoutineForm(r);}
    private void showRoutineForm(Routine existing){try{FXMLLoader l=new FXMLLoader(getClass().getResource("/com/example/proyectolp/ui/routine-form.fxml"));Parent content=l.load();RoutineFormController c=l.getController();c.setRoutine(existing==null?"":existing.name(),existing==null?"":existing.description(),existing==null?List.of():existing.exercises(),existing==null?null:existing.id());Dialog<ButtonType>d=new Dialog<>();d.setTitle(existing==null?"Nueva rutina":"Editar rutina");d.initModality(Modality.APPLICATION_MODAL);if(routineList.getScene()!=null)d.initOwner(routineList.getScene().getWindow());d.getDialogPane().setContent(content);d.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);Button ok=(Button)d.getDialogPane().lookupButton(ButtonType.OK);ok.addEventFilter(javafx.event.ActionEvent.ACTION,e->{if(!c.validateForm())e.consume();});Optional<ButtonType> result=d.showAndWait();if(result.isPresent()&&result.get()==ButtonType.OK){RoutineFormData data=new RoutineFormData(c.getName(),c.getDescription(),c.getExercises(),existing==null?null:existing.id());executor.submit(()->{try{SupabaseService s=db();WorkoutRoutineRepository rr=new WorkoutRoutineRepository(s);long id;if(data.id==null)id=rr.create(data.name,data.description);else{id=data.id;rr.update(id,data.name,data.description);}new ExerciseRepository(s).replaceForRoutine(id,data.exercises);javafx.application.Platform.runLater(this::loadData);}catch(Exception ex){javafx.application.Platform.runLater(()->messageLabel.setText(readable(ex)));}});}}catch(IOException ex){messageLabel.setText("No se pudo abrir el formulario de rutina.");}}
    private record RoutineFormData(String name,String description,List<Exercise> exercises,Long id){}
    @FXML private void deleteRoutine(){Routine r=routineList.getSelectionModel().getSelectedItem();if(r==null)return;executor.submit(()->{try{new WorkoutRoutineRepository(db()).delete(r.id());javafx.application.Platform.runLater(this::loadData);}catch(Exception e){javafx.application.Platform.runLater(()->messageLabel.setText(readable(e)));}});}
    @FXML private void startSession(){if(currentSessionId!=null&&!sessionFinished){messageLabel.setText("Finaliza la sesión actual primero.");return;}Routine r=sessionRoutine.getValue();LocalDate date=sessionDate.getValue()==null?LocalDate.now():sessionDate.getValue();sessionFinished=false;setTable.getItems().clear();sessionVolumeLabel.setText("Volumen sesión: 0");executor.submit(()->{try{long id=new WorkoutSessionRepository(db()).create(r==null?null:r.id(),date,"");javafx.application.Platform.runLater(()->{currentSessionId=id;btnSessionAttachments.setDisable(false);messageLabel.setText("Sesión iniciada.");});}catch(Exception e){javafx.application.Platform.runLater(()->messageLabel.setText(readable(e)));}});}
    @FXML private void addSet(){if(currentSessionId==null||sessionFinished){messageLabel.setText("Inicia una sesión antes de agregar series.");return;}Exercise exercise=sessionExercise.getValue();if(exercise==null){messageLabel.setText("Selecciona un ejercicio.");return;}try{BigDecimal weight=new BigDecimal(weightField.getText().trim());int reps=Integer.parseInt(repsField.getText().trim());if(weight.signum()<0||reps<=0)throw new IllegalArgumentException();int count=(int)setTable.getItems().stream().filter(s->s.exerciseName().equals(exercise.name())).count()+1;SetEntry set=new SetEntry(null,currentSessionId,exercise.name(),exercise.muscleGroup(),count,weight,reps,commentField.getText());executor.submit(()->{try{new WorkoutSetRepository(db()).create(set);javafx.application.Platform.runLater(()->{sets=new ArrayList<>(sets);sets.add(set);setTable.getItems().add(set);sessionVolumeLabel.setText("Volumen sesión: "+stats.volume(setTable.getItems()).toPlainString());refreshViews();refreshProgress();weightField.clear();repsField.clear();commentField.clear();messageLabel.setText("Serie registrada.");});}catch(Exception e){javafx.application.Platform.runLater(()->messageLabel.setText(readable(e)));}});}catch(Exception e){messageLabel.setText("Peso debe ser ≥ 0 y repeticiones un entero mayor que 0.");}}
    @FXML private void finishSession(){if(currentSessionId==null||sessionFinished)return;sessionFinished=true;timer.pause();long id=currentSessionId;String volume=stats.volume(setTable.getItems()).toPlainString();messageLabel.setText("Finalizando sesión…");executor.submit(()->{try{com.example.proyectolp.service.GamificationRuntime.service().workoutFinished(id);javafx.application.Platform.runLater(()->{messageLabel.setText("Sesión finalizada · volumen "+volume);loadData();if(dashboard!=null)dashboard.refrescar();});}catch(Exception e){javafx.application.Platform.runLater(()->messageLabel.setText(readable(e)));}});}
    @FXML private void startTimer(){try{int n=Integer.parseInt(timerConfig.getText());timer.setDurationSeconds(n);timer.start();timerLabel.setText(timer.getDisplay());}catch(Exception e){messageLabel.setText("La duración del descanso debe ser un entero positivo.");}}
    @FXML private void pauseTimer(){timer.pause();} @FXML private void resetTimer(){try{timer.setDurationSeconds(Integer.parseInt(timerConfig.getText()));}catch(Exception e){timer.reset();}}
    @FXML private void refreshProgress(){Exercise e=progressExercise.getValue();if(e==null)return;progressChart.getData().clear();XYChart.Series<String,Number> s=new XYChart.Series<>();s.setName(e.name());List<TrainingStatsService.Progress> p=stats.progress(e.name(),sessions,sets);for(var v:p)s.getData().add(new XYChart.Data<>(v.date().toString(),v.volume()));progressChart.getData().add(s);comparisonLabel.setText(stats.compareLastTwo(e.name(),sessions,sets).map(c->"Sesión anterior → actual: peso máximo "+c.previous().maxWeight()+" → "+c.current().maxWeight()+" ("+c.weightDelta()+" kg), reps máximas "+c.repsDelta()+"; volumen "+c.volumeDelta()+".").orElse("Registra dos sesiones para comparar la progresión."));}
    private void refreshViews(){List<Exercise> all=routines.stream().flatMap(r->r.exercises().stream()).toList();progressExercise.setItems(FXCollections.observableArrayList(all));LocalDate today=LocalDate.now();LocalDate week=today.with(java.time.DayOfWeek.MONDAY),month=today.withDayOfMonth(1);var w=stats.summary(sessions,sets,week,today);var m=stats.summary(sessions,sets,month,today);weeklyLabel.setText("Semana: "+w.sessions()+" sesiones · "+w.volume()+" kg·reps");monthlyLabel.setText("Mes: "+m.sessions()+" sesiones · "+m.volume()+" kg·reps");frequencyLabel.setText(String.format(Locale.ROOT,"Frecuencia: %.1f sesiones/semana",stats.sessionsPerWeek(sessions,today.minusWeeks(3),today)));renderMuscles();statsLabel.setText("Volumen semanal y mensual calculados a partir de series. Peso máximo histórico: "+all.stream().map(Exercise::name).distinct().map(n->n+" "+maxWeight(n)+" kg").reduce((a,b)->a+" · "+b).orElse("sin datos"));if(currentSessionId!=null&&!sessionFinished){List<SetEntry> current=sets.stream().filter(s->s.sessionId()==currentSessionId).toList();sessionVolumeLabel.setText("Volumen sesión: "+stats.volume(current).toPlainString());}if(!all.isEmpty()&&progressExercise.getValue()==null)progressExercise.getSelectionModel().selectFirst();}
    private void renderMuscles(){if(muscleChart==null||distributionPeriod==null)return;LocalDate today=LocalDate.now();LocalDate from="Mes".equals(distributionPeriod.getValue())?today.withDayOfMonth(1):today.with(java.time.DayOfWeek.MONDAY);muscleChart.getData().clear();stats.muscleDistribution(sessions,sets,from,today).forEach((k,v)->muscleChart.getData().add(new javafx.scene.chart.PieChart.Data(k+" "+v+"%",v.doubleValue())));muscleChart.setTitle("Distribución muscular · "+distributionPeriod.getValue());}
    private BigDecimal maxWeight(String name){return sets.stream().filter(s->s.exerciseName().equalsIgnoreCase(name)).map(SetEntry::weight).max(BigDecimal::compareTo).orElse(BigDecimal.ZERO);}
    @FXML private void volverDashboard(){javafx.scene.Scene scene=messageLabel==null?null:messageLabel.getScene();if(scene==null||dashboardRoot==null){messageLabel.setText("No se pudo recuperar la pantalla del Dashboard.");return;}scene.setRoot(dashboardRoot);if(dashboard!=null)dashboard.refrescar();}
    private String readable(Throwable e){if(e instanceof SupabaseException s&&s.getStatusCode()==404)return "Falta la tabla de entrenamiento. Ejecuta supabase/00_schema.sql.";if(e instanceof SupabaseException s&&(s.getStatusCode()==401||s.getStatusCode()==403))return "Supabase rechazó el acceso; revisa la clave y las políticas RLS.";return "Error de entrenamiento: "+(e==null?"desconocido":e.getMessage());}
}
